@Transactional
public GroupConfirmationView requestGroupConfirmation(UserPrincipal principal) {
    requireRole(principal, Role.STUDENT);
    UUID groupId = jdbc.query("select group_id from student_profiles where user_id = ?",
            (rs, row) -> rs.getObject(1, UUID.class), principal.id()).stream().findFirst()
            .orElseThrow(() -> ApiException.notFound("Профиль студента не найден"));
    if (count("select count(*) from campus_group_confirmations where student_id = ? and group_id = ? "
            + "and status = 'PENDING'", principal.id(), groupId) == 0) {
        jdbc.update("""
                insert into campus_group_confirmations(student_id, group_id, status)
                values (?, ?, 'PENDING')
                on conflict (student_id, group_id) where status = 'PENDING' do nothing
                """, principal.id(), groupId);
    }
    return jdbc.query("""
            select c.id, u.full_name, u.email::text, g.name, c.submitted_at, c.status
            from campus_group_confirmations c join users u on u.id = c.student_id
            join study_groups g on g.id = c.group_id where c.student_id = ? and c.group_id = ?
            and c.status = 'PENDING' order by c.submitted_at desc limit 1
            """, confirmationMapper(), principal.id(), groupId).get(0);
}

@Transactional(readOnly = true)
public GroupConfirmationView myGroupConfirmation(UserPrincipal principal) {
    requireRole(principal, Role.STUDENT);
    return jdbc.query("""
            select c.id, u.full_name, u.email::text, g.name, c.submitted_at, c.status
            from campus_group_confirmations c join users u on u.id = c.student_id
            join study_groups g on g.id = c.group_id where c.student_id = ?
            order by c.submitted_at desc, c.id desc limit 1
            """, confirmationMapper(), principal.id()).stream().findFirst().orElse(null);
}

@Transactional
public void decideGroupConfirmation(UserPrincipal principal, UUID confirmationId,
                                    GroupConfirmationDecision decision) {
    if (decision == null || decision.approve() == null) {
        throw ApiException.badRequest("Решение обязательно");
    }
    ConfirmationRow confirmation = jdbc.query("""
            select student_id, group_id from campus_group_confirmations
            where id = ? and status = 'PENDING' for update
            """, (rs, row) -> new ConfirmationRow(rs.getObject(1, UUID.class),
            rs.getObject(2, UUID.class)), confirmationId).stream().findFirst()
            .orElseThrow(() -> ApiException.notFound("Заявка не найдена"));
    requireGroupManager(principal, confirmation.groupId, true);
    if (decision.approve()) {
        jdbc.update("""
                update student_profiles set
                    is_group_leader = case when group_id = ? then is_group_leader else false end,
                    group_id = ?, updated_at = now()
                where user_id = ?
                """, confirmation.groupId, confirmation.groupId, confirmation.studentId);
    }
    jdbc.update("""
            update campus_group_confirmations set status = ?, reviewed_by = ?, reviewed_at = now()
            where id = ?
            """, decision.approve() ? "APPROVED" : "REJECTED", principal.id(), confirmationId);
}

@Transactional
public void assignGroupLeader(UserPrincipal principal, UUID groupId, String studentId) {
    requireGroupManager(principal, groupId, false);
    UUID leaderId = parseUuid(studentId, "studentId");
    if (count("select count(*) from student_profiles where user_id = ? and group_id = ?",
            leaderId, groupId) == 0) {
        throw ApiException.badRequest("Староста должен состоять в выбранной группе");
    }
    jdbc.update("update student_profiles set is_group_leader = false where group_id = ?", groupId);
    jdbc.update("update student_profiles set is_group_leader = true, updated_at = now() "
            + "where user_id = ? and group_id = ?", leaderId, groupId);
}

package com.ptu.backend.auth.service;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

import com.ptu.backend.academic.domain.Faculty;
import com.ptu.backend.academic.domain.StudyGroup;
import com.ptu.backend.academic.repo.FacultyRepository;
import com.ptu.backend.academic.repo.StudyGroupRepository;
import com.ptu.backend.auth.domain.RegistrationRequest;
import com.ptu.backend.auth.domain.RegistrationStatus;
import com.ptu.backend.auth.dto.CreateRegistrationRequest;
import com.ptu.backend.auth.dto.RegistrationRequestView;
import com.ptu.backend.auth.repo.RegistrationRequestRepository;
import com.ptu.backend.common.exception.ApiException;
import com.ptu.backend.config.AppProperties;
import com.ptu.backend.mail.MailService;
import com.ptu.backend.user.repo.UserRepository;

import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@Service
public class RegistrationService {

	private static final List<RegistrationStatus> ACTIVE_STATUSES = List.of(
			RegistrationStatus.PENDING_EMAIL, RegistrationStatus.EMAIL_VERIFIED);

	private final RegistrationRequestRepository requests;
	private final FacultyRepository faculties;
	private final StudyGroupRepository groups;
	private final UserRepository users;
	private final PasswordEncoder passwordEncoder;
	private final VerificationCodeService emailVerification;
	private final MailService mailService;
	private final AppProperties properties;

	public RegistrationService(RegistrationRequestRepository requests, FacultyRepository faculties,
			StudyGroupRepository groups, UserRepository users, PasswordEncoder passwordEncoder,
			VerificationCodeService emailVerification, MailService mailService, AppProperties properties) {
		this.requests = requests;
		this.faculties = faculties;
		this.groups = groups;
		this.users = users;
		this.passwordEncoder = passwordEncoder;
		this.emailVerification = emailVerification;
		this.mailService = mailService;
		this.properties = properties;
	}

	@Transactional
	public RegistrationRequestView create(CreateRegistrationRequest request) {
		String email = normalizeEmail(request.email());
		Faculty faculty = faculties.findById(request.facultyId())
				.orElseThrow(() -> ApiException.badRequest("Факультет не найден"));
		StudyGroup group = groups.findById(request.groupId())
				.orElseThrow(() -> ApiException.badRequest("Учебная группа не найдена"));
		if (!group.getFacultyId().equals(faculty.getId())) {
			throw ApiException.badRequest("Учебная группа не относится к выбранному факультету");
		}
		if (users.existsByEmailIgnoreCase(email)) {
			throw ApiException.conflict("Пользователь с таким email уже существует");
		}
		if (requests.existsByEmailIgnoreCaseAndStatusIn(email, ACTIVE_STATUSES)) {
			throw ApiException.conflict("Заявка с таким email уже существует");
		}

		RegistrationRequest entity = new RegistrationRequest();
		entity.setEmail(email);
		entity.setFullName(request.fullName().trim());
		entity.setPasswordHash(passwordEncoder.encode(request.password()));
		entity.setFacultyId(faculty.getId());
		entity.setGroupId(group.getId());
		entity.setStatus(RegistrationStatus.PENDING_EMAIL);
		entity.setExpiresAt(Instant.now().plus(properties.registration().ttl()));
		try {
			requests.saveAndFlush(entity);
		}
		catch (DataIntegrityViolationException ex) {
			throw ApiException.conflict("Заявка с таким email уже существует");
		}

		sendCode(entity);
		return RegistrationRequestView.from(entity);
	}

	@Transactional
	public void resendCode(UUID requestId) {
		RegistrationRequest request = findRequest(requestId);
		if (request.getStatus() != RegistrationStatus.PENDING_EMAIL) {
			throw ApiException.conflict("Подтверждение email для заявки недоступно");
		}
		ensureNotExpired(request);
		sendCode(request);
	}

	@Transactional
	public RegistrationRequestView verifyEmail(UUID requestId, String code) {
		RegistrationRequest request = findRequest(requestId);
		if (request.getStatus() != RegistrationStatus.PENDING_EMAIL) {
			throw ApiException.conflict("Заявка уже подтверждена или обработана");
		}
		ensureNotExpired(request);
		emailVerification.verifyCode(VerificationCodeService.SCOPE_REGISTRATION, requestId.toString(), code);
		request.setStatus(RegistrationStatus.EMAIL_VERIFIED);
		request.setEmailVerifiedAt(Instant.now());
		return RegistrationRequestView.from(request);
	}

	private void sendCode(RegistrationRequest request) {
		String code = emailVerification.issueCode(VerificationCodeService.SCOPE_REGISTRATION, request.getId().toString());
		mailService.sendVerificationCode(request.getEmail(), request.getFullName(), code,
				properties.verification().codeTtl());
	}

	private RegistrationRequest findRequest(UUID requestId) {
		return requests.findById(requestId)
				.orElseThrow(() -> ApiException.notFound("Заявка на регистрацию не найдена"));
	}

	private static void ensureNotExpired(RegistrationRequest request) {
